syntax:
int a = 10;
unsigned int b = 20;
long long c = 1000000000000LL;

example:
#include <iostream>
#include <cstdint>
int main() {
    int x = -42;
    int64_t big = 9000000000000000000LL;
    std::cout << sizeof(int) << ' ' << big << '\n';
}

#include <iostream>
#include <cmath>
int main() {
    double a = 0.1 + 0.2;
    // Không so sánh trực tiếp a == 0.3
    bool eq = std::abs(a - 0.3) < 1e-9;
    std::cout << eq << '\n';
}

#include <iostream>
int main() {
    char ch = 'a';
    char upper = ch - 32; // 'A' (mã ASCII 65)
    std::cout << upper << " (" << int(upper) << ")\n";
}

#include <iostream>
int main() {
    bool ok = 5 > 3;
    std::cout << std::boolalpha << ok << '\n'; // In ra true
}

#include <iostream>
void greet() {
    std::cout << "Xin chao!\n";
}
int main() { greet(); }

#include <vector>
#include <iostream>
int main() {
    std::vector<int> v = {1, 2, 3};
    for (const auto& item : v) std::cout << item << ' ';
}

#include <iostream>
void f(int) { std::cout << "int\n"; }
void f(int*) { std::cout << "pointer\n"; }
int main() {
    f(nullptr); // Gọi chính xác f(int*)
}
